import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';
void main(){WidgetsFlutterBinding.ensureInitialized();runApp(const TunaApp());}
class TunaApp extends StatelessWidget{const TunaApp({super.key});@override Widget build(BuildContext c)=>MaterialApp(title:'حسابات بيع السمك',debugShowCheckedModeBanner:false,theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xff087f8c)),useMaterial3:true),home:const Home());}
class SaleInvoice{final String buyer,date,note;final double kg,price,paid;SaleInvoice(this.buyer,this.date,this.note,this.kg,this.price,this.paid);double get total=>kg*price;double get balance=>total-paid;Map<String,dynamic> toJson()=>{'buyer':buyer,'date':date,'note':note,'kg':kg,'price':price,'paid':paid};factory SaleInvoice.fromJson(Map<String,dynamic> j)=>SaleInvoice(j['buyer'],j['date'],j['note']??'',(j['kg'] as num).toDouble(),(j['price'] as num).toDouble(),(j['paid'] as num).toDouble());}
class Home extends StatefulWidget{const Home({super.key});@override State<Home> createState()=>_HomeState();}
class _HomeState extends State<Home>{List<SaleInvoice> sales=[];List<String> buyerNames=[];bool ready=false;
String get today=>DateTime.now().toIso8601String().substring(0,10);
double get salesToday=>sales.where((x)=>x.date.startsWith(today)).fold(0,(s,x)=>s+x.total);
double get kgToday=>sales.where((x)=>x.date.startsWith(today)).fold(0,(s,x)=>s+x.kg);
double get debts=>sales.fold(0,(s,x)=>s+x.balance);
@override void initState(){super.initState();load();}
Future<void> load()async{final p=await SharedPreferences.getInstance();sales=(p.getStringList('sales')??[]).map((s)=>SaleInvoice.fromJson(jsonDecode(s))).toList();buyerNames=p.getStringList('buyers')??[];if(mounted)setState(()=>ready=true);}
Future<void> save()async{final p=await SharedPreferences.getInstance();await p.setStringList('sales',sales.map((s)=>jsonEncode(s.toJson())).toList());await p.setStringList('buyers',buyerNames);}
Future<void> invoice()async{
final n=TextEditingController(),k=TextEditingController(),pr=TextEditingController(text:'6500'),pd=TextEditingController(text:'0'),note=TextEditingController();String type='آجل';
final ok=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:const Text('فاتورة بيع'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:n,decoration:const InputDecoration(labelText:'اسم المشتري')),TextField(controller:k,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'الكيلو')),TextField(controller:pr,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'سعر الكيلو')),TextField(controller:pd,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'المدفوع')),DropdownButtonFormField<String>(initialValue:type,items:['نقد','آجل'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>type=v??type,decoration:const InputDecoration(labelText:'نوع البيع')),TextField(controller:note,decoration:const InputDecoration(labelText:'ملاحظات'))])),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('حفظ'))]);
if(ok!=true)return;final kg=double.tryParse(k.text),price=double.tryParse(pr.text),paid=double.tryParse(pd.text.isEmpty?'0':pd.text)??0;
if(n.text.trim().isEmpty||kg==null||kg<=0||price==null||price<=0||paid<0||paid>kg*price||(type=='نقد'&&paid!=kg*price)){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تحقق من البيانات؛ النقد يجب أن يكون كاملًا')));return;}
sales.insert(0,SaleInvoice(n.text.trim(),DateTime.now().toIso8601String(),note.text.trim(),kg,price,paid));if(!buyerNames.contains(n.text.trim()))buyerNames.add(n.text.trim());await save();if(mounted)setState((){});
}
Future<void> addBuyer()async{final n=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:const Text('مشتري جديد'),content:TextField(controller:n,decoration:const InputDecoration(labelText:'اسم المشتري')),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('رجوع')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('حفظ'))]));if(ok==true&&n.text.trim().isNotEmpty&&!buyerNames.contains(n.text.trim())){buyerNames.add(n.text.trim());await save();if(mounted)setState((){});}}
Future<void> pay(SaleInvoice s)async{final c=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:Text('تحصيل من '+s.buyer),content:TextField(controller:c,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'مبلغ التحصيل')),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('استلام'))]));if(ok!=true)return;final v=double.tryParse(c.text);if(v==null||v<=0||v>s.balance){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('قيمة التحصيل غير صحيحة')));return;}final idx=sales.indexOf(s);sales[idx]=SaleInvoice(s.buyer,s.date,s.note,s.kg,s.price,s.paid+v);await save();if(mounted)setState((){});}
Widget card(String title,String value,String unit)=>Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Text(title),Text(value,style:const TextStyle(fontWeight:FontWeight.bold,fontSize:22)),Text(unit)])));
@override Widget build(BuildContext c){if(!ready)return const Scaffold(body:Center(child:CircularProgressIndicator()));return Scaffold(appBar:AppBar(title:const Text('حسابات بيع وشراء السمك')),floatingActionButton:FloatingActionButton.extended(onPressed:invoice,icon:const Icon(Icons.add),label:const Text('فاتورة بيع')),body:ListView(padding:const EdgeInsets.all(12),children:[GridView.count(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),crossAxisCount:2,children:[card('مبيعات اليوم',salesToday.toStringAsFixed(0),'ريال'),card('كيلو اليوم',kgToday.toStringAsFixed(2),'كيلو'),card('الديون',debts.toStringAsFixed(0),'ريال'),card('المشترون',buyerNames.length.toString(),'مشتري')]),Row(children:[const Expanded(child:Text('الفواتير',style:TextStyle(fontSize:20))),IconButton(onPressed:addBuyer,icon:const Icon(Icons.person_add))]),if(sales.isEmpty)const Text('لا توجد فواتير بعد'),...sales.map((s)=>Card(child:ListTile(title:Text(s.buyer),subtitle:Text(s.kg.toString()+' كجم × '+s.price.toStringAsFixed(0)+'\n'+s.date.substring(0,10)),trailing:Text('باقي '+s.balance.toStringAsFixed(0)),onTap:()=>pay(s)))),const Text('المشترون',style:TextStyle(fontSize:20)),...buyerNames.map((b)=>ListTile(leading:const Icon(Icons.person),title:Text(b),subtitle:Text('رصيد: '+sales.where((s)=>s.buyer==b).fold(0.0,(a,s)=>a+s.balance).toStringAsFixed(0)+' ريال')))]));}
}
